// Regenerates shared/src/abi.ts from the Foundry build output. Run after `forge build`.
import { readFileSync, writeFileSync } from 'node:fs';

const artifact = JSON.parse(
  readFileSync(new URL('../contracts/out/SettlementOracle.sol/SettlementOracle.json', import.meta.url), 'utf8'),
);
const out =
  '// Generated by scripts/export-abi.mjs from contracts/out. Do not edit by hand.\n' +
  `export const settlementOracleAbi = ${JSON.stringify(artifact.abi, null, 2)} as const;\n`;
writeFileSync(new URL('../shared/src/abi.ts', import.meta.url), out);
console.log(`wrote shared/src/abi.ts (${artifact.abi.length} entries)`);
